(function() {
    'use strict';

    class ExecutionGapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ExecutionGap — Strategy-to-Operations Alignment';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    title: 'Q1: Strategy Kickoff',
                    description: 'The board has approved a bold corporate strategy: pivot from legacy product lines to digital-first solutions. Your mandate is to cascade this strategy across four departments — Product, Sales, Operations, and People. Resistance runs high as most managers view this as yet another corporate initiative that will fade. The sales team guards legacy customer relationships worth $8M annually. Begin the alignment process without triggering organizational paralysis.',
                    resistanceMod: 0,
                    coherenceMod: 0,
                    moraleMod: 0
                },
                {
                    title: 'Q2: Early Friction',
                    description: 'The Sales VP has formally objected to customer migration targets, citing risk to $8M in legacy revenue. The Operations team has interpreted digital transformation as a software purchasing exercise rather than a process overhaul. Early signs of the execution gap are emerging — what looked clear at board level is being distorted as it flows through organizational layers.',
                    resistanceMod: 5,
                    coherenceMod: -2,
                    moraleMod: 0
                },
                {
                    title: 'Q3: Budget Battle',
                    description: 'Mid-year budget review. The CFO is questioning strategic spending that has yet to produce visible returns. Finance wants proof of ROI before releasing next-quarter funds. Meanwhile, the Product team is adding features nobody requested (gold-plating), and cross-departmental coordination meetings keep getting canceled due to operational fires.',
                    resistanceMod: 3,
                    coherenceMod: -1,
                    moraleMod: -2
                },
                {
                    title: 'Q4: Talent Crunch',
                    description: 'The People department reports an inability to hire digital talent at the pace required — compensation benchmarks exceed current salary bands by 30%. Operations has purchased three new software platforms but integrated none of them. Year-end pressure mounts as the board expects a formal progress update within 90 days.',
                    resistanceMod: 4,
                    coherenceMod: 0,
                    moraleMod: -3
                },
                {
                    title: 'Q5: Competitive Pressure',
                    description: 'A major competitor has launched a similar strategic initiative with significant marketing investment. The board demands acceleration of your execution timeline. Market analysts are now comparing both transformation programs publicly. This external pressure creates urgency — use it to overcome internal inertia, but avoid panic-driven decisions that sacrifice coherence.',
                    resistanceMod: -3,
                    coherenceMod: 0,
                    moraleMod: 1
                },
                {
                    title: 'Q6: Cultural Clash',
                    description: 'Cultural resistance reaches a peak. Middle managers are openly challenging the new incentive structures, calling them unfair and poorly designed. Two senior engineers and a top-performing sales manager have signaled intent to leave. Informal power networks within the organization are actively working against the strategic shift.',
                    resistanceMod: 8,
                    coherenceMod: -2,
                    moraleMod: -4
                },
                {
                    title: 'Q7: Inflection Point',
                    description: 'A turning point emerges. The Product team — among the first to align — delivers a digital solution generating $2M in new revenue. Success stories from early-adopter departments are spreading through the organization. Skeptics are beginning to pay attention. The narrative is shifting from "this will never work" to "maybe there is something here."',
                    resistanceMod: -5,
                    coherenceMod: 3,
                    moraleMod: 4
                },
                {
                    title: 'Q8: Strategy Review',
                    description: 'Final quarterly review before the annual board assessment. Performance data is mixed — some departments have transformed remarkably while others still lag behind. The board will evaluate total execution effectiveness, cumulative value created, and organizational readiness for the next strategic horizon. Make final adjustments count.',
                    resistanceMod: 0,
                    coherenceMod: 0,
                    moraleMod: 0
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 5000000,
                    coherence: 15,
                    resistance: 75,
                    executionScore: 31,
                    morale: 65,
                    quarterlyRevenue: 12000000,
                    totalValueCreated: 0,
                    totalSpent: 0,
                    coherenceHistory: [],
                    resistanceHistory: [],
                    executionHistory: [],
                    revenueHistory: [],
                    moraleHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    budgetShift: 10,
                    alignment: 5,
                    communication: 3,
                    incentive: 2
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var bsInput = document.getElementById('budgetShiftInput');
            if (bsInput) decisions.budgetShift = parseFloat(bsInput.value);

            var alInput = document.getElementById('alignmentInput');
            if (alInput) decisions.alignment = parseInt(alInput.value);

            var comInput = document.getElementById('communicationInput');
            if (comInput) decisions.communication = parseInt(comInput.value);

            var incInput = document.getElementById('incentiveInput');
            if (incInput) decisions.incentive = parseInt(incInput.value);

            if (isNaN(decisions.budgetShift) || decisions.budgetShift < 0 || decisions.budgetShift > 40) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_budget_shift'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.alignment) || decisions.alignment < 1 || decisions.alignment > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_alignment'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.communication) || decisions.communication < 1 || decisions.communication > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_communication'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.incentive) || decisions.incentive < 1 || decisions.incentive > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_incentive'), 'warning'
                );
                return false;
            }

            var ds = window.mySimulation.state.domainState;
            var quarterCost = decisions.budgetShift * 40000 + decisions.communication * 60000 + decisions.incentive * 50000;
            if (quarterCost > ds.budget) {
                var fmtB = function(n){ return '$' + Math.round(n).toLocaleString(); };
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_insufficient_budget') + ' ' +
                    window.mySimulation.t('budget_need_have').replace('{need}', fmtB(quarterCost)).replace('{have}', fmtB(ds.budget)),
                    'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var quarterCost = d.budgetShift * 40000 + d.communication * 60000 + d.incentive * 50000;
            ds.budget -= quarterCost;
            ds.totalSpent += quarterCost;

            var resistanceDelta = -(d.communication * 3.5) - (d.incentive * 2.5) + Math.max(0, d.alignment - 5) * 2.2 - 1.5;
            resistanceDelta += round.resistanceMod;
            resistanceDelta += (Math.random() - 0.5) * 4;
            ds.resistance = Math.max(0, Math.min(100, ds.resistance + resistanceDelta));

            var coherenceDelta = (d.alignment * 1.4) + (d.communication * 2.0) + (d.incentive * 1.0) - (ds.resistance * 0.07);
            coherenceDelta += round.coherenceMod;
            coherenceDelta += (Math.random() - 0.5) * 3;
            ds.coherence = Math.max(0, Math.min(100, ds.coherence + coherenceDelta));

            var moraleDelta = -(d.alignment * 0.9) + (d.communication * 1.4) - (d.incentive * 0.6) + (ds.coherence > 50 ? 2.5 : -1);
            moraleDelta += round.moraleMod;
            moraleDelta += (Math.random() - 0.5) * 3;
            ds.morale = Math.max(0, Math.min(100, ds.morale + moraleDelta));

            ds.executionScore = Math.round(ds.coherence * 0.45 + (100 - ds.resistance) * 0.30 + ds.morale * 0.25);
            ds.executionScore = Math.max(0, Math.min(100, ds.executionScore));

            var revenueMultiplier = 1 + (ds.executionScore - 25) * 0.004;
            revenueMultiplier = Math.max(0.85, Math.min(1.3, revenueMultiplier));
            ds.quarterlyRevenue = Math.round(12000000 * revenueMultiplier);
            var valueCreated = ds.quarterlyRevenue - 12000000;
            ds.totalValueCreated += Math.max(0, valueCreated);

            ds.coherenceHistory.push(Math.round(ds.coherence));
            ds.resistanceHistory.push(Math.round(ds.resistance));
            ds.executionHistory.push(ds.executionScore);
            ds.revenueHistory.push(ds.quarterlyRevenue);
            ds.moraleHistory.push(Math.round(ds.morale));

            var results = {
                period: state.currentPeriod,
                quarterCost: quarterCost,
                coherence: Math.round(ds.coherence),
                resistance: Math.round(ds.resistance),
                morale: Math.round(ds.morale),
                executionScore: ds.executionScore,
                quarterlyRevenue: ds.quarterlyRevenue,
                valueCreated: valueCreated,
                budget: ds.budget,
                totalValueCreated: ds.totalValueCreated
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('coherenceDisplay', 'domainState.coherence',
                (v) => Math.round(v) + '/100');
            uiManager.bind('resistanceDisplay', 'domainState.resistance',
                (v) => Math.round(v) + '/100');
            uiManager.bind('executionDisplay', 'domainState.executionScore',
                (v) => Math.round(v) + '/100');
            uiManager.bind('moraleDisplay', 'domainState.morale',
                (v) => Math.round(v) + '/100');
            uiManager.bind('revenueDisplay', 'domainState.quarterlyRevenue',
                (v) => '$' + Math.round(v).toLocaleString());
        }

        getChartConfig() {
            return {
                alignmentChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('coherence_label'),
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: this._t('resistance_label'),
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: this._t('chart_morale'),
                                data: [],
                                borderColor: '#f39c12',
                                backgroundColor: 'rgba(243,156,18,0.1)',
                                borderWidth: 2,
                                borderDash: [5, 5],
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_align_title') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: this._t('chart_score_axis') } }
                        }
                    }
                },
                performanceChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_revenue_label'),
                                data: [],
                                backgroundColor: 'rgba(22,160,133,0.6)',
                                borderColor: '#16a085',
                                borderWidth: 2,
                                yAxisID: 'y'
                            },
                            {
                                label: this._t('execution_label'),
                                data: [],
                                type: 'line',
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_perf_title') }
                        },
                        scales: {
                            y: {
                                beginAtZero: false,
                                position: 'left',
                                title: { display: true, text: this._t('chart_revenue_axis') }
                            },
                            y1: {
                                beginAtZero: true,
                                max: 100,
                                position: 'right',
                                title: { display: true, text: this._t('execution_label') },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.coherenceHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                alignmentChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.resistanceHistory },
                        { data: state.domainState.moraleHistory }
                    ]
                },
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.executionHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var num = function(v, d){ return (v === undefined || v === null || isNaN(v)) ? d : v; };
            var execScores = history.map(function(r) { return r.results ? num(r.results.executionScore, 0) : 0; });
            var totalValue = history.reduce(function(s, r) { return s + (r.results ? Math.max(0, num(r.results.valueCreated, 0)) : 0); }, 0);
            var finalExec = execScores.length ? execScores[execScores.length - 1] : 0;
            var avgExec = execScores.reduce(function(s, v) { return s + v; }, 0) / execScores.length;
            var lastRec = history[history.length - 1].results || {};
            var lastCoherence = num(lastRec.coherence, 0);
            var lastResistance = num(lastRec.resistance, 100);

            var performance = this._t('perf_failure');
            if (finalExec >= 70 && lastCoherence >= 70 && lastResistance <= 30) {
                performance = this._t('perf_excellence');
            } else if (finalExec >= 55 && lastCoherence >= 55) {
                performance = this._t('perf_effective');
            } else if (finalExec >= 35) {
                performance = this._t('perf_partial');
            }

            var insights = [];
            if (lastCoherence >= 70) {
                insights.push(this._t('insight_coh_high'));
            } else if (lastCoherence < 40) {
                insights.push(this._t('insight_coh_low'));
            }
            if (lastResistance <= 25) {
                insights.push(this._t('insight_res_low'));
            } else if (lastResistance > 60) {
                insights.push(this._t('insight_res_high'));
            }
            if (totalValue > 3000000) {
                insights.push(this._t('insight_val_high'));
            } else if (totalValue < 500000) {
                insights.push(this._t('insight_val_low'));
            }

            return {
                finalExecutionScore: finalExec,
                averageExecutionScore: Math.round(avgExec),
                finalCoherence: lastCoherence,
                finalResistance: lastResistance,
                totalValueCreated: totalValue,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.domainState.resistance > 70) {
                return window.mySimulation.t('hint_high_resistance');
            }
            if (state.domainState.coherence < 30 && state.currentPeriod > 3) {
                return window.mySimulation.t('hint_low_coherence');
            }
            if (state.domainState.morale < 40) {
                return window.mySimulation.t('hint_low_morale');
            }
            if (state.domainState.budget < 500000) {
                return window.mySimulation.t('hint_low_budget');
            }
            if (state.domainState.executionScore > 60) {
                return window.mySimulation.t('hint_good_execution');
            }
            if (results && results.valueCreated < 0) {
                return window.mySimulation.t('hint_negative_value');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.budgetShift', label: 'Budget Shift (%)', i18nKey: 'col_budget_shift' },
                { key: 'decisions.alignment', label: 'Alignment', i18nKey: 'col_alignment' },
                { key: 'decisions.communication', label: 'Communication', i18nKey: 'col_communication' },
                { key: 'decisions.incentive', label: 'Incentive', i18nKey: 'col_incentive' },
                { key: 'results.coherence', label: 'Coherence', i18nKey: 'col_coherence' },
                { key: 'results.resistance', label: 'Resistance', i18nKey: 'col_resistance' },
                { key: 'results.executionScore', label: 'Execution', i18nKey: 'col_execution' },
                { key: 'results.quarterlyRevenue', label: 'Revenue', i18nKey: 'col_revenue', formatter: function(v) { return '$' + Math.round(v).toLocaleString(); } },
                { key: 'results.quarterCost', label: 'Cost', i18nKey: 'col_cost', formatter: function(v) { return '$' + Math.round(v).toLocaleString(); } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                      `ExecutionGap — Strategy-to-Operations Alignment`,
                    subtitle:                   `Translate corporate strategy into operational reality across organizational silos`,
                    period_label:               `Quarter`,
                    period_of:                  `of`,
                    briefing_heading:           `Quarterly Briefing`,
                    budget_label:               `Discretionary Budget`,
                    coherence_label:            `Strategic Coherence`,
                    resistance_label:           `Organizational Resistance`,
                    execution_label:            `Execution Score`,
                    morale_label:               `Organization Morale`,
                    revenue_label:              `Quarterly Revenue`,
                    decisions_heading:          `Strategic Decisions`,
                    budget_shift_label:         `Budget Reallocation (%)`,
                    budget_shift_placeholder:   `0-40`,
                    budget_shift_hint:          `Percentage shifted from legacy to strategic initiatives (0-40%)`,
                    alignment_label:            `Alignment Pressure`,
                    alignment_placeholder:      `1-10`,
                    alignment_hint:             `How hard you push strategic alignment across departments (1-10)`,
                    communication_label:        `Communication Investment`,
                    communication_placeholder:  `1-5`,
                    communication_hint:         `Strategy communication cascade intensity (1-5)`,
                    incentive_label:            `Incentive Redesign Pace`,
                    incentive_placeholder:      `1-5`,
                    incentive_hint:             `Speed of incentive structure realignment (1-5)`,
                    submit_btn:                 `Submit Quarter`,
                    undo_btn:                   `Undo Last Quarter`,
                    warning_budget_shift:       `Budget reallocation must be between 0% and 40%`,
